SELECT ?label ?instanceOf ?instanceOfLabel ?formula WHERE {
  OPTIONAL { wd:Q415638 rdfs:label ?label . FILTER(LANG(?label) = "en") }
  OPTIONAL { wd:Q415638 wdt:P31 ?instanceOf . }
  OPTIONAL { wd:Q415638 wdt:P274 ?formula . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 10

